; ============================================================
; NTC program - generated by NTC BASIC (VB style BASIC to NTC)
; platform: md (Sega Mega Drive / Genesis (68000)), starts in turbo mode
; ============================================================

			org 0

;## ntc_md_vectors ntc_md_boot
; the 68000's vectors and the cartridge header (the compiler puts this first, at 0)
			dc.l $00FF8000				; the supervisor stack
			dc.l ntc_md_entry
			dc.l ntc_md_ex2, ntc_md_ex3, ntc_md_ex4, ntc_md_ex5
			dc.l ntc_md_ex6, ntc_md_ex7, ntc_md_ex8, ntc_md_ex9
			dc.l ntc_md_ex10, ntc_md_ex11
			dcb.l 12, ntc_md_exx		; 12-23
			dc.l ntc_md_exx				; 24 spurious
			dc.l ntc_md_rte				; 25 level 1
			dc.l ntc_md_rte				; 26 level 2 (external)
			dc.l ntc_md_rte				; 27 level 3
			dc.l ntc_md_hint			; 28 level 4 (line)
			dc.l ntc_md_rte				; 29 level 5
			dc.l ntc_md_vint			; 30 level 6 (frame)
			dc.l ntc_md_rte				; 31 level 7
			dcb.l 16, ntc_md_exx		; 32-47 TRAP #0-15
			dcb.l 16, ntc_md_exx		; 48-63
; the header ($100): mdbuild.py puts in the name, the ROM's end and the checksum
			dc.b "SEGA MEGA DRIVE "
			dc.b "(C)NTC  2026.OCT"
			dc.b "NTC BASIC                                       "
			dc.b "NTC BASIC                                       "
			dc.b "GM 00000000-00"
			dc.w 0						; checksum
			dc.b "J6              "		; I/O: 3 and 6 button pads
			dc.l $00000000, $003FFFFF	; ROM start, end
			dc.l $00FF0000, $00FFFFFF	; RAM start, end
			dc.b "            "			; no SRAM
			dc.b "            "
			dc.b "                                        "
			dc.b "JUE             "		; every region

NTC_TERM	equ 0		; Option Terminal: 0 none, 1 VT52, 2 ANSI (CP/M)
NTC_STRMAX	equ 40		; the longest string (library buffers, temps)
NTC_MEMBANKS	equ 64		; Option Memory: the most 64K banks the Memory class looks for
NTC_ROMENABLE	equ 0		; Option RomEnable (cpcfw, cpcmin): the start code starts the ROMs
NTC_ROMLIB	equ 0		; 1 = the library is the keyword ROM (Library: ROM; ntcRomAsm builds it)
NTC_WINHOLE	equ 0		; 1 = the program is built round an Option Reserve range over the window #4000-#7FFF
NTC_BUFSIZE	equ 2048		; the library's buffer (ntc_buf: FileSystem, Memory.Copy): Option Buffer
NTC_CPMGFX	equ 0		; 1 = CP/M: Graphics draws on an Amstrad CPC's screen (2.2: #C000, Plus: block 1 from common memory)
NTC_RS		macro			; the real stack: the thread position kept in ntc_ip
			move.l sp, ntc_ip
			movea.l ntc_csp, sp
			endm
NTC_TS		macro			; back to the thread
			movea.l ntc_ip, sp
			endm

ntc_start:
			move.l sp, ntc_csp		; the real stack (the library's jsr calls)
			lea main_thread, sp
